mapper.select:
SELECT NULL AS categoryId, c.name AS categoryName, g.id AS goodsId, g.goods_code AS goodsCode, g.name AS goodsName, 0 AS goodsCount, i.quantity AS stockQty, i.cost_price AS costPrice, i.cost_amount AS costAmount, (i.quantity * g.retail_price) AS retailValue, CASE WHEN i.quantity <= 0 THEN 'OUT' WHEN i.quantity <= g.safety_stock_lower THEN 'WARNING' WHEN g.safety_stock_upper IS NOT NULL AND i.quantity >= g.safety_stock_upper THEN 'OVERSTOCK' ELSE 'NORMAL' END AS stockStatus FROM goods g JOIN inventory i ON i.goods_id = g.id LEFT JOIN category c ON c.id = g.category_id WHERE g.status = 1
AND g.category_id = #{categoryId}
ORDER BY i.cost_amount DESC, g.id

SELECT g.id AS goodsId, g.goods_code AS goodsCode, g.name AS goodsName, g.category_id AS categoryId, c.name AS categoryName, COALESCE(i.quantity, 0) AS stockQty, COALESCE(i.cost_amount, 0) AS costAmount, NULL AS beginAmount, NULL AS avgAmount, NULL AS saleCostAmount, NULL AS returnCostAmount, NULL AS flowAmount, NULL AS turnoverRate, NULL AS turnoverDays FROM goods g JOIN inventory i ON i.goods_id = g.id LEFT JOIN category c ON c.id = g.category_id WHERE g.status = 1
AND g.category_id = #{categoryId}
ORDER BY i.cost_amount DESC, g.id

